-- The built-in "Resolve conflicts" Pipeline, as a flow (`straightLineFlow`), unless the user has one of that name already.
INSERT INTO "pipelines" ("id", "name", "description", "stages") VALUES ('resolve-conflicts', 'Resolve conflicts', 'Merges the base branch into a pull request''s branch, resolves the conflicts, tests, then pushes the branch to the same pull request.', '[{"kind":"agent","key":"resolve-conflicts","name":"Resolve conflicts","duty":"implements","brief":"Call update_branch to merge the base branch into this branch: a merge, never a rebase. Resolve each conflicted file keeping what both sides meant, and remove every conflict marker. Run the Test with run_project_command test and fix what it finds. When you can''t finish, end the Stage failed and write why in the Handover note.","session":"fresh","budget":150000,"optional":false,"routes":[{"to":"test","condition":null}],"place":{"column":0,"row":0}},{"kind":"script","key":"test","name":"Test","command":"test","optional":false,"onFailure":{"goBackTo":"resolve-conflicts","rounds":2},"routes":[{"to":"publish","condition":null}],"place":{"column":1,"row":0}},{"kind":"script","key":"publish","name":"Publish","command":"publish","publishTarget":"branch-only","optional":false,"routes":[{"to":null,"condition":null}],"place":{"column":2,"row":0}}]'::jsonb) ON CONFLICT DO NOTHING;--> statement-breakpoint
